import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0xd19a62);scene.fog=new THREE.FogExp2(0xc58b57,.0095);
const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,420);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;mount.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xffdfae,0x64503b,2.1);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffd69a,3.3);sun.position.set(-45,65,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={sand:mat(0xb78a58),road:mat(0x876646),wood:mat(0x785034),wood2:mat(0x996c42),darkwood:mat(0x4a3326),plaster:mat(0xc4a47b),red:mat(0x8e4630),roof:mat(0x51392c),metal:mat(0x403b33),green:mat(0x526344),cactus:mat(0x416044),stone:mat(0x877862),gold:mat(0xc6984f),black:mat(0x211c18),white:mat(0xd9c7a6)};
function box(parent,x,y,z,sx,sy,sz,material,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,x,y,z,r1,r2,h,material,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material,scaleY=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),material);m.position.set(x,y,z);m.scale.y=scaleY;m.castShadow=true;parent.add(m);return m}
const heightAt=(x,z)=>Math.max(0,Math.sin(x*.075+1)*Math.cos(z*.067)*1.5+Math.sin(z*.12-x*.05)*.7+3.4*Math.exp(-((x-48)**2+(z+30)**2)/1500)+2.5*Math.exp(-((x+44)**2+(z-18)**2)/1200));
function makeTerrain(){const n=110,size=240,geo=new THREE.PlaneGeometry(size,size,n,n);geo.rotateX(-Math.PI/2);const p=geo.attributes.position,colors=[];const a=new THREE.Color(0xa98254),b=new THREE.Color(0x9c7048),c=new THREE.Color(0xc09a67);for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=heightAt(x,z);p.setY(i,h);const col=h>2.3?c.clone().lerp(a,Math.min(.6,(h-2.3)*.14)):b.clone().lerp(a,Math.random()*.15);colors.push(col.r,col.g,col.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));mesh.receiveShadow=true;scene.add(mesh);const road=box(scene,0,.025,-5,13,.08,104,mats.road);road.material=new THREE.MeshStandardMaterial({color:0x92704c,roughness:1});road.receiveShadow=true;for(let i=0;i<14;i++){const x=(Math.random()-.5)*8,z=-54+i*7;const track=new THREE.Mesh(new THREE.CircleGeometry(.12+Math.random()*.12,6),mat(0x796044));track.rotation.x=-Math.PI/2;track.position.set(x,.08,z);scene.add(track)}}
makeTerrain();
function makeBuilding(x,z,w,d,h,color,sign=''){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const wall=mat(color),wood=i=>i?mats.wood2:mats.wood;box(g,0,h/2,0,w,h,d,wall);box(g,0,h+.16,0,w+.55,.32,d+.55,mats.roof); // roof cap
// false-front parapet and facade trim
box(g,0,h+.78,-d/2-.08,w*.86,1.25,.18,wall);box(g,0,h+1.43,-d/2-.09,w*.94,.12,.28,mats.darkwood);
for(let i=-1;i<=1;i++){box(g,i*w*.36,.9,-d/2-.1,.13,1.8,.15,mats.darkwood);box(g,i*w*.36,2.0,-d/2-.13,.18,.1,.2,mats.gold)}
// front door and windows
box(g,0,.95,-d/2-.14,.8,1.9,.12,mats.darkwood);box(g,0,.9,-d/2-.22,.56,1.65,.03,mats.wood2);
for(const sx of [-1,1]){box(g,sx*w*.25,1.55,-d/2-.15,.68,.62,.12,mats.darkwood);box(g,sx*w*.25,1.55,-d/2-.23,.48,.43,.025,mat(0x40505a));box(g,sx*w*.25,1.55,-d/2-.25,.07,.5,.04,mats.gold);box(g,sx*w*.25,1.55,-d/2-.25,.55,.06,.04,mats.gold)}
// porch roof and posts
box(g,0,2.25,-d/2-.8,w+.8,.16,1.5,mats.roof);for(let sx of [-1,0,1])cyl(g,sx*w*.44,1.08,-d/2-1.42,.075,.075,2.15,mats.darkwood,6);
box(g,0,.09,-d/2-.75,w+.8,.18,1.55,mats.darkwood);
// sign board
if(sign){box(g,0,h+1.02,-d/2-.24,Math.min(w*.8,sign.length*.27+1),.42,.12,mats.darkwood);const canvas=document.createElement('canvas');canvas.width=512;canvas.height=100;const ctx=canvas.getContext('2d');ctx.fillStyle='#3c2a1e';ctx.fillRect(0,0,512,100);ctx.fillStyle='#e7c68b';ctx.font='bold 54px Georgia';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(sign.toUpperCase(),256,53);const tex=new THREE.CanvasTexture(canvas);const board=new THREE.Mesh(new THREE.PlaneGeometry(Math.min(w*.8,sign.length*.27+1)-.13,.3),new THREE.MeshBasicMaterial({map:tex,transparent:true}));board.position.set(0,h+1.02,-d/2-.31);g.add(board)}
// roof steps
for(let i=-1;i<=1;i++)box(g,i*.9,h+.38,-d/2-.4,.1,.65,.1,mats.wood);
return g}
makeBuilding(-10,-13,8,7,4.2,0xb8895b,'GENERAL STORE');makeBuilding(10,-17,9,8,4.4,0xb94f37,'SALOON');makeBuilding(-11,-31,9,8,4.1,0xc0a276,'SHERIFF');makeBuilding(11,-35,8,7,4.2,0x9a6c45,'STABLES');makeBuilding(-18,1,7,7,3.8,0x9e6644,'HOTEL');makeBuilding(18,3,8,7,4,0xb6966d,'DRY GOODS');
// boardwalks, water tower, hitching posts, barrels, hay and scenery
for(const x of [-10,10,-11,11,-18,18]){box(scene,x,.12,-24,10,.22,1.55,mats.darkwood);for(let z=-27;z<-17;z+=2.6)cyl(scene,x+(x<0?1:-1),.72,z,.07,.07,1.2,mats.wood,6)}
const tower=new THREE.Group();tower.position.set(-22,0,-12);scene.add(tower);for(const x of [-1.4,1.4])for(const z of [-1.4,1.4]){box(tower,x,3,z,.14,6,.14,mats.wood,0,0,(x*z>0?.14:-.14));box(tower,x,5.9,z,.14,1.1,.14,mats.wood)}box(tower,0,6.1,0,3.3,1.2,3.3,mats.wood2);cyl(tower,0,6.85,0,1.7,1.7,.3,mats.darkwood,4);
for(let i=0;i<8;i++){const barrel=new THREE.Group();barrel.position.set(-5+(i%4)*3,.45,-21+Math.floor(i/4)*4);scene.add(barrel);cyl(barrel,0,0,0,.42,.38,.9,i%2?mats.wood:mats.wood2,12);for(let y of [-.3,.3]){const ring=new THREE.Mesh(new THREE.TorusGeometry(.4,.035,5,12),mats.metal);ring.rotation.x=Math.PI/2;ring.position.y=y;barrel.add(ring)}}
// distant mesas and sun
for(let i=0;i<12;i++){const x=-105+i*19,z=-92-Math.random()*13,h=10+Math.random()*17,w=13+Math.random()*14;const m=new THREE.Mesh(new THREE.ConeGeometry(w,h,5),mat(i%2?0x9a6246:0xaa7451));m.position.set(x,h*.3,z);m.rotation.y=Math.random()*2;m.receiveShadow=true;scene.add(m)}
const sunDisc=new THREE.Mesh(new THREE.CircleGeometry(7,32),new THREE.MeshBasicMaterial({color:0xffd58b}));sunDisc.position.set(-65,42,-150);sunDisc.lookAt(0,20,0);scene.add(sunDisc);
function addCactus(x,z,s=1){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);g.scale.setScalar(s);scene.add(g);cyl(g,0,1.25,0,.25,.32,2.5,mats.cactus,7);cyl(g,-.43,1.02,0,.17,.2,1.1,mats.cactus,7);cyl(g,-.68,1.55,0,.16,.17,.72,mats.cactus,7);cyl(g,.43,.98,0,.18,.2,1,mats.cactus,7);cyl(g,.62,1.46,0,.16,.16,.75,mats.cactus,7);}
for(let i=0;i<75;i++){let x,z;do{x=(Math.random()-.5)*180;z=(Math.random()-.5)*180}while(Math.abs(x)<20&&z<8&&z>-48);if(Math.random()<.54)addCactus(x,z,.65+Math.random()*.9);else{const r=.3+Math.random()*.7;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(r,0),mats.stone);rock.position.set(x,heightAt(x,z)+r*.45,z);rock.scale.y=.5;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;scene.add(rock)}}

