function updateHUD(){document.querySelector('#ammo').textContent=ammo;document.querySelector('#health').style.width=health+'%';document.querySelector('#progress').textContent=`OUTLAWS: ${enemies.filter(e=>!e.alive).length} / 4`;if(!enemies.some(e=>e.alive)&&!won){won=true;finish(true)}}
function begin(){started=true;intro.classList.add('hidden');hud.style.display='block';if(innerWidth<700)document.querySelector('#touchpad').style.display='block';renderer.domElement.requestPointerLock?.();say('Keep your eyes open, stranger.');}
