document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement});document.addEventListener('mousemove',e=>{if(locked&&started){yaw-=e.movementX*.0022;pitch=Math.max(-.55,Math.min(.5,pitch+e.movementY*.0018))}});
