function reload(){if(reloading||ammo===6||reserve<=0||!started)return;reloading=true;say('Reloading…');setTimeout(()=>{if(dead||won)return;const n=Math.min(6-ammo,reserve);ammo+=n;reserve-=n;reloading=false;updateHUD()},1050)}
