renderer.domElement.addEventListener('touchstart',e=>{if(!started||e.touches.length===0)return;const t=e.touches[0];lastTouch={x:t.clientX,y:t.clientY}},{passive:true});renderer.domElement.addEventListener('touchmove',e=>{if(!lastTouch||!e.touches.length)return;const t=e.touches[0];yaw-=(t.clientX-lastTouch.x)*.006;pitch=Math.max(-.55,Math.min(.5,pitch+(t.clientY-lastTouch.y)*.004));lastTouch={x:t.clientX,y:t.clientY}},{passive:true});renderer.domElement.addEventListener('touchend',()=>lastTouch=null);document.querySelector('#touchfire').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});

