const stick=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickId=null,stickX=0,stickY=0,lastTouch=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);stickX=e.clientX;stickY=e.clientY;});stick.addEventListener('pointermove',e=>{if(e.pointerId!==stickId)return;let dx=e.clientX-stickX,dy=e.clientY-stickY,r=Math.min(38,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);dx=Math.cos(a)*r;dy=Math.sin(a)*r;knob.style.transform=`translate(${dx}px,${dy}px)`;keys.KeyW=dy<-10;keys.KeyS=dy>10;keys.KeyA=dx<-10;keys.KeyD=dx>10});function releaseStick(){stickId=null;knob.style.transform='';keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=false}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
