/* Phone-first input, safe-area spacing, and compact landscape layout. */
html,body{height:100%;height:100dvh;overscroll-behavior:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
canvas{touch-action:none}
button{touch-action:manipulation}
@media(max-width:700px){
  .brand{top:calc(14px + env(safe-area-inset-top))}
  .mission{top:calc(38px + env(safe-area-inset-top))}
  .status{top:calc(16px + env(safe-area-inset-top))}
  .health-wrap{left:calc(16px + env(safe-area-inset-left));bottom:calc(20px + env(safe-area-inset-bottom))}
  .ammo{right:calc(16px + env(safe-area-inset-right));bottom:calc(18px + env(safe-area-inset-bottom))}
  .hint{bottom:calc(59px + env(safe-area-inset-bottom))}
  .touchpad{height:calc(154px + env(safe-area-inset-bottom));padding-bottom:env(safe-area-inset-bottom)}
  .stick-area{left:calc(18px + env(safe-area-inset-left));bottom:calc(18px + env(safe-area-inset-bottom));width:118px;height:118px}
  .stick-knob{left:36px;top:36px;width:44px;height:44px}
  .fire-touch{right:calc(22px + env(safe-area-inset-right));bottom:calc(24px + env(safe-area-inset-bottom));width:78px;height:78px;font-size:12px;font-weight:500;box-shadow:0 3px 14px #0006}
  .reload-touch{position:absolute;right:calc(108px + env(safe-area-inset-right));bottom:calc(39px + env(safe-area-inset-bottom));height:48px;padding:0 13px;border:1px solid #e8d4b188;border-radius:24px;background:#33271cbb;color:#f5dfb6;font:10px 'DM Mono',monospace;letter-spacing:.08em;pointer-events:auto;touch-action:none}
  .start{min-height:50px}
  .screen-card button{min-height:48px}
}
@media(max-width:700px) and (orientation:landscape){
  .brand{display:none}
  .mission{top:calc(10px + env(safe-area-inset-top));width:190px;padding:6px 9px}
  .mission h2{font-size:17px;margin:2px 0}
  .mission p{font-size:12px}
  .progress{font-size:10px;margin-top:3px}
  .status{top:calc(10px + env(safe-area-inset-top))}
  .hint{display:none}
  .health-wrap{bottom:calc(12px + env(safe-area-inset-bottom))}
  .ammo{bottom:calc(10px + env(safe-area-inset-bottom))}
  .touchpad{height:calc(130px + env(safe-area-inset-bottom))}
  .stick-area{width:96px;height:96px;bottom:calc(12px + env(safe-area-inset-bottom))}
  .stick-knob{left:25px;top:25px}
  .fire-touch{width:68px;height:68px;bottom:calc(17px + env(safe-area-inset-bottom))}
  .reload-touch{right:calc(96px + env(safe-area-inset-right));bottom:calc(27px + env(safe-area-inset-bottom));height:44px}
  .intro{padding:10px 24px;max-height:100dvh;overflow:auto}
  .kicker{margin-bottom:8px}
  .intro h1{font-size:clamp(38px,9vh,58px);margin-bottom:8px}
  .intro .rule{margin:12px 0 9px}
  .intro p{font-size:14px;margin-bottom:12px}
  .mobile-help{margin-top:8px}
}
@media(max-height:420px) and (max-width:900px){.toast{top:16%;font-size:11px;padding:7px 12px}.screen-card{padding:20px 24px}.screen-card h2{font-size:27px}}
</style>

